def test_basic():
    words = [["a", "b", "c"], ["a", "b", "d"], ["a", "b", "e"]]
    assert solution.most_common_pair(words) == ("a", "b")

def test_repeated_word():
    assert solution.most_common_pair([["x", "y"], ["x", "y"]]) == ("x", "y")

def test_tie_break():
    assert solution.most_common_pair([["b", "c"], ["a", "d"]]) == ("a", "d")

def test_no_pairs():
    assert solution.most_common_pair([]) is None
    assert solution.most_common_pair([["a"], ["b"]]) is None

def test_frequency_beats_alphabet():
    words = [["a", "b"], ["z", "z"], ["z", "z"]]
    assert solution.most_common_pair(words) == ("z", "z")

def test_does_not_mutate():
    words = [["a", "b"], ["c", "d"]]
    before = [w[:] for w in words]
    solution.most_common_pair(words)
    assert words == before
